<?php
use App\Enums\ApplicationStatus;use App\Enums\StudentStatus;use App\Enums\UserRole;use App\Models\Certificate;use App\Models\Course;use App\Models\CourseEnrollment;use App\Models\EnrollmentForm;use App\Models\Student;use App\Models\User;
test('certificate issuance snapshots student and formation identity',function(){$admin=User::factory()->create(['role'=>UserRole::ADMIN]);$course=Course::create(['title'=>'Informatique','code'=>'INFO-CERT','duration_hours'=>40,'price'=>0,'is_certified'=>true,'is_active'=>true]);$form=EnrollmentForm::create(['course_id'=>$course->id,'title'=>'Session','start_date'=>today()->subMonth(),'end_date'=>today(),'min_students'=>1,'max_students'=>10,'groups_count'=>1,'students_per_group'=>10,'is_active'=>true]);$student=Student::create(['first_name'=>'Lina','last_name'=>'Kaci','phone'=>'1','status'=>StudentStatus::COMPLETED,'is_active'=>false]);$enrollment=CourseEnrollment::create(['enrollment_form_id'=>$form->id,'student_id'=>$student->id,'status'=>ApplicationStatus::REGISTERED,'first_name'=>'Lina','last_name'=>'Kaci','email'=>'cert@example.test','phone'=>'1','confirmation_token'=>str()->uuid(),'group_number'=>1,'registered_at'=>now()]);$this->actingAs($admin)->post(route('admin.certificates.store'),['course_enrollment_id'=>$enrollment->id,'type'=>'success_certificate','issue_date'=>today()->toDateString(),'result'=>'Réussi'])->assertSessionHasNoErrors();$certificate=Certificate::firstOrFail();expect($certificate->student_name)->toBe('Lina Kaci')->and($certificate->formation_name)->toBe('Informatique')->and($certificate->verification_token)->toHaveLength(64);});
test('school reports require administration access',function(){$teacher=User::factory()->create(['role'=>UserRole::TEACHER]);$this->actingAs($teacher)->get('/admin/reports')->assertForbidden();});
